### Description

Since upgrading to the latest version of ai-sdk v5, I've been getting this error.

Here's the configuration I have:
```  const result = streamText({
    messages: modelMessagesWithSystemPrompt,
    model: anthropic("claude-4-sonnet-20250514"),
    headers: {
      "anthropic-beta": "extended-cache-ttl-2025-04-11",
    },
   tools: [REDACTED]
    maxOutputTokens: 42_000,
    providerOptions: {
      anthropic: {
        thinking: { type: "enabled", budgetTokens: 12000 },
      },
    },
    prepareStep: async (step) => {
      if (step.stepNumber === 0) {
        const usefulContextMessage = await enrichUserMessageWithIntent(
          lastUserMessageText ?? "",
        );
        if (!usefulContextMessage) {
          return step;
        }

        return {
          ...step,
          messages: [
            ...step.messages,
            {
              content: `${usefulContextMessage} \n\n The user message is below:\n${lastUserMessageText}`,
              role: "user" as const,
            },
          ],
        };
      }

      return step;
    },
    stopWhen: stepCountIs(30),
    onFinish: async (finishResult) => {
      await sandbox.betaPause();
      logger.log(
        `Usage: ${finishResult.usage.inputTokens} input tokens, \n ${finishResult.usage.outputTokens} output tokens, \n cached: ${finishResult.usage.cachedInputTokens} cached input tokens. \n ${finishResult.usage.totalTokens} total tokens.`,
      );
    },
    onError: async (error) => {
      logger.error(JSON.stringify(error, null, 2));
      await sandbox.betaPause();
    },
    experimental_repairToolCall: async ({ toolCall, tools, inputSchema }) =>
      repairToolCall(toolCall, tools, inputSchema),
  });
```

### AI SDK Version

```
 "@ai-sdk/anthropic": "^2.0.35",
 "@ai-sdk/openai": "^2.0.53",
"ai": "^5.0.76",  
```


